_REF_WORDS = [
    (r"\bArts\.", "Art."), (r"\bAnnexes\b", "Anexele"), (r"\bAnnex\b", "Anexa"),
    (r"\brecitals\b", "considerentele"), (r"\bRecitals\b", "Considerentele"), (r"\brecital\b", "considerentul"),
    (r"\bRegulation \(EU\)", "Regulamentul (UE)"), (r"\bReg\. \(EU\)", "Reg. (UE)"),
    (r"\bDirective \(EU\)", "Directiva (UE)"), (r"\bas amended by\b", "modificat prin"), (r"\bas amended\b", "astfel cum a fost modificat"),
    (r"\blast subparagraph\b", "ultimul paragraf"), (r"\blast subpara\.", "ultimul paragraf"),
    (r"\bpoint\b", "punctul"), (r"\band\b", "și"), (r"\bSection\b", "Secțiunea"),
    (r"\bCommission Guidelines on the AI system definition\b", "Ghidul Comisiei privind definiția sistemului AI"),
    (r"\bCommission Guidelines on prohibited practices\b", "Ghidul Comisiei privind practicile interzise"),
    (r"\bCommission guidelines on high-risk classification\b", "Ghidul Comisiei privind clasificarea sistemelor cu risc ridicat"),
    (r"\bEDPB Guidelines\b", "Ghidul CEPD"), (r"\bRecommendation\b", "Recomandarea"), (r"\bProposal\b", "Propunerea"),
    (r"\(pending\)", "(în negociere)"), (r"\bFeb\b", "feb."), (r"\(EU\)", "(UE)"),
]
REF_START = re.compile(r"^(Art\.|Arts\.|Annex|Annexes|Recitals?|Proposal|Commission)")


def ref(text):
    """Converts an English legal citation to Romanian wording ("Annex III" -> "Anexa III")."""
    out = text
    for pat, rep in _REF_WORDS:
        out = re.sub(pat, rep, out)
    return out


